#include <stdio.h>

int main(void) {
    // for
    for (int i = 1; i <= 5; i++) {
        printf("%d ", i);
    }
    printf("\n");   // 1 2 3 4 5

    // while
    int j = 1;
    while (j <= 5) {
        printf("%d ", j);
        j++;
    }
    printf("\n");   // 1 2 3 4 5

    // do-while (pasti jalan minimal sekali)
    int k = 10;
    do {
        printf("k = %d\n", k);
        k++;
    } while (k < 3);   // k = 10 (cetak sekali walau kondisi langsung false)

    // break & continue
    for (int i = 1; i <= 10; i++) {
        if (i == 5) continue;
        if (i == 8) break;
        printf("%d ", i);
    }
    printf("\n");   // 1 2 3 4 6 7

    // nested loop: pola segitiga bintang
    for (int i = 1; i <= 4; i++) {
        for (int j = 1; j <= i; j++) {
            printf("*");
        }
        printf("\n");
    }
    return 0;
}

