int main(void) {
    char kotak[] = "halo";          // 5 byte MILIK KITA, isinya disalin dari literal
    const char *tunjuk = "halo";    // cuma alamat; literalnya read-only

    kotak[0] = 'H';                 // BOLEH: yang diubah salinan sendiri
